package cn.mop.api;

import cn.mop.domain.*;
import cn.mop.persistence.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class WeComControllerTest {
    final String tenant="55000000-0000-4000-8000-000000000001",actor="55000000-0000-4000-8000-000000000011";
    PlatformRepository platform;PostgresWeComRepository repository;WeComService service;ProjectIdentityService identity;SessionService sessions;WeComController controller;
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);repository=mock(PostgresWeComRepository.class);service=mock(WeComService.class);identity=mock(ProjectIdentityService.class);sessions=mock(SessionService.class);controller=new WeComController(service,repository,platform,identity,sessions);when(service.tenant()).thenReturn(tenant);when(service.corp()).thenReturn("wwsynthetic12345678");when(service.agent()).thenReturn(1000001);when(service.testUser()).thenReturn("Synthetic");when(service.callback()).thenReturn("https://mop.example.test/api/v1/auth/wecom/callback");when(platform.membership(actor,tenant)).thenReturn(Optional.of(new Membership(actor,tenant,"padmin",3,true)));when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(x->{((Runnable)x.getArgument(6)).run();return ((Supplier<?>)x.getArgument(7)).get();});}
    MockHttpServletRequest request(String path,String body){var r=new MockHttpServletRequest("POST","/api/v1"+path);r.setUserPrincipal(()->actor);r.getSession().setAttribute("mop.tenant_id",tenant);r.setAttribute("mop.trace_id","synthetic-wecom");r.addHeader("Idempotency-Key","synthetic-command");r.setContentType("application/json");r.setContent(body.getBytes(StandardCharsets.UTF_8));return r;}
    @Test void testMessageHasFixedRecipientAndContentAndReturnsDurable202(){var r=request("/wecom/test-messages","{\"expected_version\":0}");var response=new MockHttpServletResponse();when(repository.enqueueTest(any(),anyString(),anyInt(),anyString(),anyString())).thenReturn(Map.of("id",actor,"status","QUEUED"));controller.test(r,response);assertEquals(202,response.getStatus());verify(repository).enqueueTest(argThat(a->a.tenantId().equals(tenant)&&a.actorId().equals(actor)),eq("wwsynthetic12345678"),eq(1000001),eq("Synthetic"),eq(WeComService.TEST_MESSAGE));}
    @Test void callerCannotOverrideRecipientOrContent(){for(String body:List.of("{\"expected_version\":0,\"recipient\":\"other\"}","{\"expected_version\":0,\"text\":\"injected\"}","{\"expected_version\":1}")){assertEquals(400,assertThrows(DomainException.class,()->controller.test(request("/wecom/test-messages",body),new MockHttpServletResponse())).status);}verify(repository,never()).enqueueTest(any(),anyString(),anyInt(),anyString(),anyString());}
    @Test void foreignTenantIs404BeforeProviderAccess(){var r=request("/wecom/test-messages","{\"expected_version\":0}");r.getSession().setAttribute("mop.tenant_id","55000000-0000-4000-8000-000000000002");assertEquals(404,assertThrows(DomainException.class,()->controller.test(r,new MockHttpServletResponse())).status);verify(service,never()).verifyMember(anyString());}
    @Test void viewerCannotSendAdminTest(){when(platform.membership(actor,tenant)).thenReturn(Optional.of(new Membership(actor,tenant,"viewer",3,true)));assertEquals(403,assertThrows(DomainException.class,()->controller.test(request("/wecom/test-messages","{\"expected_version\":0}"),new MockHttpServletResponse())).status);}
    @Test void callbackWithoutBrowserCorrelationNeverCallsProviderAndDoesNotInvalidateExistingSession()throws Exception{var r=request("/auth/wecom/callback","");r.setMethod("GET");r.addParameter("state","a".repeat(43));r.addParameter("code","synthetic-code");var existing=r.getSession();var response=new MockHttpServletResponse();controller.callback(r,response);assertEquals("/login?auth_error=WECOM_LOGIN_STATE_INVALID",response.getRedirectedUrl());assertSame(existing,r.getSession(false));verify(service,never()).identity(anyString());}
    @Test void externalMemberCannotBecomeImplicitPlatformAccount()throws Exception{var r=request("/auth/wecom/callback","");r.addParameter("state","a".repeat(43));r.addParameter("code","synthetic-code");r.setCookies(new jakarta.servlet.http.Cookie("MOP_WECOM_CORRELATION","b".repeat(43)));when(service.consumeLogin(anyString(),anyString())).thenReturn(true);when(service.identity(anyString())).thenReturn("Synthetic");when(repository.login(anyString(),anyString(),anyString())).thenReturn(Optional.empty());var response=new MockHttpServletResponse();controller.callback(r,response);assertEquals("/login?auth_error=WECOM_IDENTITY_NOT_BOUND",response.getRedirectedUrl());verifyNoInteractions(sessions);}
    @Test void loginStartRejectsCrossOriginBeforeCreatingState(){var r=request("/auth/wecom/start","{\"mode\":\"web\"}");r.addHeader("Origin","https://other.example.test");assertEquals(403,assertThrows(DomainException.class,()->controller.start(r,new MockHttpServletResponse())).status);verify(service,never()).startLogin(anyString());}
    @Test void loginCorrelationCookieAllowsTopLevelProviderReturnWithoutWeakeningProjectCookie(){var r=request("/auth/wecom/start","{\"mode\":\"web\"}");r.setScheme("https");r.setServerName("mop.example.test");r.setServerPort(443);when(service.startLogin("web")).thenReturn(new WeComService.LoginStart("a".repeat(43),"b".repeat(43),"https://login.work.weixin.qq.com/"));var response=new MockHttpServletResponse();controller.start(r,response);var cookie=response.getCookie("MOP_WECOM_CORRELATION");assertNotNull(cookie);assertTrue(cookie.isHttpOnly());assertTrue(cookie.getSecure());assertEquals("Lax",cookie.getAttribute("SameSite"));assertEquals("/api/v1/auth/wecom",cookie.getPath());assertNull(response.getCookie("MOP_SESSION"));}
    @Test void callbackOriginMustMatchBrowserOrigin(){var r=request("/auth/wecom/start","{\"mode\":\"web\"}");assertEquals("WECOM_CALLBACK_ORIGIN_MISMATCH",assertThrows(DomainException.class,()->controller.start(r,new MockHttpServletResponse())).code);verify(service,never()).startLogin(anyString());}
    @Test void verifiedCallbackUsesBoundProjectUserAndCurrentAuthenticationRevision()throws Exception{
        var r=request("/auth/wecom/callback","");r.addParameter("state","a".repeat(43));r.addParameter("code","synthetic-code");r.setCookies(new jakarta.servlet.http.Cookie("MOP_WECOM_CORRELATION","b".repeat(43)));
        when(service.consumeLogin(anyString(),anyString())).thenReturn(true);when(service.identity(anyString())).thenReturn("Synthetic");when(repository.login(tenant,"wwsynthetic12345678","Synthetic")).thenReturn(Optional.of(new PostgresWeComRepository.Login(actor,tenant,1)));
        var accounts=mock(ProjectIdentityRepository.class);when(identity.repository()).thenReturn(accounts);when(accounts.sessionState(actor)).thenReturn(Optional.of(new ProjectIdentityRepository.SessionState(9,false)));when(accounts.policy()).thenReturn(Map.of("idle_minutes",20));
        var response=new MockHttpServletResponse();controller.callback(r,response);assertEquals("/assets",response.getRedirectedUrl());
        var ordered=inOrder(sessions,platform);ordered.verify(sessions).establishProjectSession(argThat(auth->auth.getName().equals(actor)&&auth.getPrincipal() instanceof WeComController.WeComPrincipal p&&p.securityVersion()==9&&p.identitySource().equals("wecom")),eq(20),eq(r),eq(response));ordered.verify(platform).audit(eq(actor),eq(tenant),eq("wecom.login"),eq("session"),isNull(),eq("SUCCEEDED"),anyString(),anyString());
    }
}
